1	const NODE_TYPES = new Set(['trigger', 'form', 'condition', 'action', 'end']);
2	const FIELD_TYPES = new Set(['string', 'number', 'integer', 'boolean']);
3	const FORBIDDEN_SEGMENTS = new Set(['__proto__', 'prototype', 'constructor']);
4	const STRING_BOUNDS = new Set(['minLength', 'maxLength']);
5	const NUMBER_BOUNDS = new Set(['min', 'max']);
6	
7	function assertPlainObject(value, label) {
8	  if (!value || typeof value !== 'object' || Array.isArray(value)) {
9	    throw new TypeError(`${label} must be an object`);
10	  }
11	}
12	
13	function isUsableObject(value) {
14	  return value !== null && typeof value === 'object' && !Array.isArray(value);
15	}
16	
17	function valueMatchesType(value, type) {
18	  if (type === 'string') return typeof value === 'string';
19	  if (type === 'boolean') return typeof value === 'boolean';
20	  if (typeof value !== 'number') return false;
21	  if (type === 'number') return Number.isFinite(value);
22	  return Number.isInteger(value);
23	}
24	
25	function valueSatisfiesBounds(value, spec) {
26	  if (spec.type === 'string') {
27	    const length = [...value].length;
28	    if (spec.minLength !== undefined && length < spec.minLength) return false;
29	    if (spec.maxLength !== undefined && length > spec.maxLength) return false;
30	  } else if (spec.type === 'number' || spec.type === 'integer') {
31	    if (spec.min !== undefined && value < spec.min) return false;
32	    if (spec.max !== undefined && value > spec.max) return false;
33	  }
34	  return true;
35	}
36	
37	function compileFormSchema(node) {
38	  if (!Object.hasOwn(node, 'schema') || node.schema === undefined) return null;
39	  if (!isUsableObject(node.schema)) {
40	    throw new Error(`form node ${node.id}: schema must be an object`);
41	  }
42	  if (!Array.isArray(node.schema.fields)) {
43	    throw new Error(`form node ${node.id}: schema.fields must be an array`);
44	  }
45	
46	  const seenSegments = [];
47	  const compiled = [];
48	  node.schema.fields.forEach((field, index) => {
49	    const label = `form node ${node.id} field ${field && isUsableObject(field) && typeof field.path === 'string' && field.path ? field.path : `#${index}`}`;
50	    if (!isUsableObject(field)) {
51	      throw new Error(`${label}: field must be an object`);
52	    }
53	    if (typeof field.path !== 'string' || field.path.length === 0) {
54	      throw new Error(`form node ${node.id} field #${index}: path must be a non-empty string`);
55	    }
56	    const segments = field.path.split('.');
57	    if (segments.some(part => part.length === 0)) {
58	      throw new Error(`${label}: path must not contain empty segments`);
59	    }
60	    if (segments.some(part => FORBIDDEN_SEGMENTS.has(part))) {
61	      throw new Error(`${label}: path must not contain __proto__, prototype or constructor segments`);
62	    }
63	    for (const previous of seenSegments) {
64	      const shared = Math.min(previous.length, segments.length);
65	      let prefix = true;
66	      for (let i = 0; i < shared; i += 1) {
67	        if (previous[i] !== segments[i]) { prefix = false; break; }
68	      }
69	      if (prefix && previous.length === segments.length) {
70	        throw new Error(`${label}: duplicate field path`);
71	      }
72	      if (prefix) {
73	        throw new Error(`${label}: field paths must not be parent and child of each other`);
74	      }
75	    }
76	    seenSegments.push(segments);
77	
78	    if (!FIELD_TYPES.has(field.type)) {
79	      throw new Error(`${label}: unknown field type ${field.type}`);
80	    }
81	    const spec = { path: field.path, segments, type: field.type, required: false, hasDefault: false };
82	
83	    if (Object.hasOwn(field, 'required')) {
84	      if (typeof field.required !== 'boolean') {
85	        throw new Error(`${label}: required must be a boolean`);
86	      }
87	      spec.required = field.required;
88	    }
89	
90	    const applicableBounds = field.type === 'string' ? STRING_BOUNDS
91	      : (field.type === 'number' || field.type === 'integer') ? NUMBER_BOUNDS
92	      : new Set();
93	    for (const bound of ['minLength', 'maxLength', 'min', 'max']) {
94	      if (!Object.hasOwn(field, bound) || field[bound] === undefined) continue;
95	      if (!applicableBounds.has(bound)) {
96	        throw new Error(`${label}: ${bound} does not apply to ${field.type} fields`);
97	      }
98	      const value = field[bound];
99	      if (field.type === 'string') {
100	        if (typeof value !== 'number' || !Number.isInteger(value) || value < 0) {
101	          throw new Error(`${label}: ${bound} must be a non-negative integer`);
102	        }
103	      } else if (typeof value !== 'number' || !Number.isFinite(value)) {
104	        throw new Error(`${label}: ${bound} must be a finite number`);
105	      }
106	      spec[bound] = value;
107	    }
108	    if (spec.minLength !== undefined && spec.maxLength !== undefined && spec.minLength > spec.maxLength) {
109	      throw new Error(`${label}: minLength must not be greater than maxLength`);
110	    }
111	    if (spec.min !== undefined && spec.max !== undefined && spec.min > spec.max) {
112	      throw new Error(`${label}: min must not be greater than max`);
113	    }
114	
115	    if (Object.hasOwn(field, 'default') && field.default !== undefined) {
116	      const fallback = field.default;
117	      if (!valueMatchesType(fallback, spec.type)) {
118	        throw new Error(`${label}: default value does not match field type ${spec.type}`);
119	      }
120	      if (!valueSatisfiesBounds(fallback, spec)) {
121	        throw new Error(`${label}: default value violates field constraints`);
122	      }
123	      spec.hasDefault = true;
124	      spec.default = fallback;
125	    }
126	
127	    compiled.push(spec);
128	  });
129	
130	  return compiled;
131	}
132	
133	const MAX_CONDITION_DEPTH = 32;
134	
135	function parsePathSegments(path, label) {
136	  if (typeof path !== 'string' || path.length === 0) {
137	    throw new Error(`${label}: path must be a non-empty string`);
138	  }
139	  const segments = path.split('.');
140	  if (segments.some(part => part.length === 0)) {
141	    throw new Error(`${label}: path must not contain empty segments`);
142	  }
143	  if (segments.some(part => FORBIDDEN_SEGMENTS.has(part))) {
144	    throw new Error(`${label}: path must not contain __proto__, prototype or constructor segments`);
145	  }
146	  return segments;
147	}
148	
149	function isComparableConstant(value) {
150	  return value === null || typeof value === 'string' || typeof value === 'boolean'
151	    || (typeof value === 'number' && Number.isFinite(value));
152	}
153	
154	function toComparableNumber(value) {
155	  // Objects and arrays never participate in numeric comparison, even though
156	  // Number([]) === 0; everything else uses JS numeric conversion.
157	  if (value !== null && typeof value === 'object') return null;
158	  const converted = Number(value);
159	  return Number.isFinite(converted) ? converted : null;
160	}
161	
162	// Validates an output reference of the shape
163	// `{ "nodeId": "risk-check", "path": "risk.score" }` (path optional). The
164	// reference itself must be a non-array object, nodeId must name an action
165	// node in this definition (matched as a whole string — dots are literal),
166	// and path, when present, follows the same segment rules as input paths.
167	function compileOutputReference(ref, nodes, label) {
168	  if (!isUsableObject(ref)) {
169	    throw new Error(`${label}: output reference must be a non-array object`);
170	  }
171	  if (typeof ref.nodeId !== 'string' || ref.nodeId.length === 0) {
172	    throw new Error(`${label}: nodeId must be a non-empty string naming an action node`);
173	  }
174	  const target = nodes.get(ref.nodeId);
175	  if (!target) {
176	    throw new Error(`${label}: nodeId "${ref.nodeId}" does not name a node in this workflow`);
177	  }
178	  if (target.type !== 'action') {
179	    throw new Error(`${label}: nodeId "${ref.nodeId}" must name an action node`);
180	  }
181	  let segments = [];
182	  if (Object.hasOwn(ref, 'path')) {
183	    segments = parsePathSegments(ref.path, `${label} path`);
184	  }
185	  return { nodeId: ref.nodeId, segments };
186	}
187	
188	// Walks every condition node (including untaken branches) and turns it into a
189	// pre-validated, pre-resolved structure. Any malformed condition throws with a
190	// node id and a `$`-style child position, before the workflow can execute.
191	function compileCondition(condition, nodes, nodeId, position = '$', depth = 1) {
192	  if (depth > MAX_CONDITION_DEPTH) {
193	    throw new Error(`condition node ${nodeId} at ${position}: conditions must not be nested deeper than ${MAX_CONDITION_DEPTH} levels`);
194	  }
195	  if (!isUsableObject(condition)) {
196	    throw new Error(`condition node ${nodeId} at ${position}: condition must be an object`);
197	  }
198	
199	  const comboKeys = [];
200	  if (Object.hasOwn(condition, 'all')) comboKeys.push('all');
201	  if (Object.hasOwn(condition, 'any')) comboKeys.push('any');
202	  if (Object.hasOwn(condition, 'not')) comboKeys.push('not');
203	  if (comboKeys.length > 1) {
204	    throw new Error(`condition node ${nodeId} at ${position}: condition must use only one of all, any or not`);
205	  }
206	
207	  const comparisonKeys = ['field', 'outputField', 'operator', 'value', 'valueField', 'valueOutputField'];
208	  const presentComparisonKeys = comparisonKeys.filter(key => Object.hasOwn(condition, key));
209	
210	  if (comboKeys.length === 1) {
211	    if (presentComparisonKeys.length > 0) {
212	      throw new Error(`condition node ${nodeId} at ${position}: ${comboKeys[0]} condition must not mix in field, outputField, operator, value, valueField or valueOutputField`);
213	    }
214	    const key = comboKeys[0];
215	    if (key === 'not') {
216	      return { kind: 'not', child: compileCondition(condition.not, nodes, nodeId, `${position}.not`, depth + 1) };
217	    }
218	    if (!Array.isArray(condition[key])) {
219	      throw new Error(`condition node ${nodeId} at ${position}: ${key} must be an array of conditions`);
220	    }
221	    if (condition[key].length === 0) {
222	      throw new Error(`condition node ${nodeId} at ${position}: ${key} must not be empty`);
223	    }
224	    return {
225	      kind: key,
226	      children: condition[key].map((child, index) =>
227	        compileCondition(child, nodes, nodeId, `${position}.${key}[${index}]`, depth + 1)),
228	    };
229	  }
230	
231	  const where = `condition node ${nodeId} at ${position}`;
232	  const hasField = Object.hasOwn(condition, 'field');
233	  const hasOutputField = Object.hasOwn(condition, 'outputField');
234	  if ((!hasField && !hasOutputField) || !Object.hasOwn(condition, 'operator')) {
235	    throw new Error(`${where}: condition must be a comparison (field and operator) or a compound (all, any or not)`);
236	  }
237	  if (hasField && hasOutputField) {
238	    throw new Error(`${where}: condition must specify exactly one of field or outputField`);
239	  }
240	
241	  if (!['eq', 'gte', 'lte', 'exists'].includes(condition.operator)) {
242	    throw new Error(`${where}: unknown condition operator: ${condition.operator}`);
243	  }
244	
245	  let left;
246	  if (hasField) {
247	    left = { kind: 'input', label: 'field', segments: parsePathSegments(condition.field, `${where} field`) };
248	  } else {
249	    left = {
250	      kind: 'output', label: 'outputField',
251	      ref: compileOutputReference(condition.outputField, nodes, `${where} outputField`),
252	    };
253	  }
254	
255	  if (condition.operator === 'exists') {
256	    const unexpected = presentComparisonKeys.filter(key =>
257	      key === 'value' || key === 'valueField' || key === 'valueOutputField');
258	    if (unexpected.length > 0) {
259	      throw new Error(`${where}: exists only takes field and operator (outputField may name the left side)`);
260	    }
261	    return { kind: 'comparison', operator: 'exists', left };
262	  }
263	
264	  const hasValue = Object.hasOwn(condition, 'value');
265	  const hasValueField = Object.hasOwn(condition, 'valueField');
266	  const hasValueOutput = Object.hasOwn(condition, 'valueOutputField');
267	  const rightCount = [hasValue, hasValueField, hasValueOutput].filter(Boolean).length;
268	  if (rightCount !== 1) {
269	    throw new Error(`${where}: condition must specify exactly one of value or valueField (or valueOutputField)`);
270	  }
271	
272	  let right;
273	  if (hasValue) {
274	    if (!isComparableConstant(condition.value)) {
275	      throw new Error(`${where}: value must be a string, finite number, boolean or null`);
276	    }
277	    right = { kind: 'constant', label: 'value', value: condition.value };
278	    if (condition.operator !== 'eq') {
279	      const numericValue = toComparableNumber(condition.value);
280	      if (numericValue === null) {
281	        throw new Error(`${where}: value for ${condition.operator} must convert to a finite number`);
282	      }
283	      right.numericValue = numericValue;
284	    }
285	  } else if (hasValueField) {
286	    if (typeof condition.valueField !== 'string') {
287	      throw new Error(`${where} valueField: path must be a non-empty string`);
288	    }
289	    right = {
290	      kind: 'input', label: 'valueField',
291	      segments: parsePathSegments(condition.valueField, `${where} valueField`),
292	    };
293	  } else {
294	    right = {
295	      kind: 'output', label: 'valueOutputField',
296	      ref: compileOutputReference(condition.valueOutputField, nodes, `${where} valueOutputField`),
297	    };
298	  }
299	
300	  return { kind: 'comparison', operator: condition.operator, left, right };
301	}
302	
303	const formSchemas = new WeakMap();
304	const compiledConditions = new WeakMap();
305	const successorTargets = new WeakMap();
306	const nodeDependencies = new WeakMap();
307	const actionBindings = new WeakMap();
308	
309	const RETRY_FIELDS = ['attempts', 'initialDelayMs', 'backoffFactor', 'maxDelayMs'];
310	const DEFAULT_RETRY = { attempts: 1, initialDelayMs: 0, backoffFactor: 1, maxDelayMs: 0 };
311	
312	function isIntegerIn(value, min, max) {
313	  return typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max;
314	}
315	
316	// A retry block is either absent (one attempt, no waiting) or present with all
317	// four parameters together, each within the same ranges the engine enforces
318	// for business action retries and compensation retries alike.
319	function compileRetry(config, label) {
320	  if (!isUsableObject(config)) {
321	    throw new Error(`${label}: retry must be an object`);
322	  }
323	  const missing = RETRY_FIELDS.filter(field => !Object.hasOwn(config, field) || config[field] === undefined);
324	  if (missing.length > 0) {
325	    throw new Error(`${label}: retry config must define all of ${RETRY_FIELDS.join(', ')} together (missing: ${missing.join(', ')})`);
326	  }
327	  if (!isIntegerIn(config.attempts, 1, 10)) {
328	    throw new Error(`${label}: retry.attempts must be an integer between 1 and 10`);
329	  }
330	  if (!isIntegerIn(config.initialDelayMs, 0, 60000)) {
331	    throw new Error(`${label}: retry.initialDelayMs must be an integer between 0 and 60000 milliseconds`);
332	  }
333	  if (!isIntegerIn(config.maxDelayMs, 0, 60000)) {
334	    throw new Error(`${label}: retry.maxDelayMs must be an integer between 0 and 60000 milliseconds`);
335	  }
336	  if (typeof config.backoffFactor !== 'number' || !Number.isFinite(config.backoffFactor)
337	    || config.backoffFactor < 1 || config.backoffFactor > 4) {
338	    throw new Error(`${label}: retry.backoffFactor must be a finite number between 1 and 4`);
339	  }
340	  if (config.maxDelayMs < config.initialDelayMs) {
341	    throw new Error(`${label}: retry.maxDelayMs must not be less than retry.initialDelayMs`);
342	  }
343	  return {
344	    attempts: config.attempts,
345	    initialDelayMs: config.initialDelayMs,
346	    backoffFactor: config.backoffFactor,
347	    maxDelayMs: config.maxDelayMs,
348	  };
349	}
350	
351	// An action node either keeps the legacy `message` behavior, names a business
352	// operation the caller supplies at run time, and/or declares a compensation
353	// operation that undoes its business effect. Both retry blocks are optional
354	// and, absent, mean exactly one attempt with no waiting.
355	function compileAction(node) {
356	  let name = null;
357	  if (Object.hasOwn(node, 'operation') && node.operation !== undefined) {
358	    if (typeof node.operation !== 'string' || node.operation.trim().length === 0) {
359	      throw new Error(`action node ${node.id}: operation must be a non-empty string name`);
360	    }
361	    name = node.operation;
362	  }
363	
364	  let retry = { ...DEFAULT_RETRY };
365	  if (Object.hasOwn(node, 'retry') && node.retry !== undefined) {
366	    if (!name) {
367	      throw new Error(`action node ${node.id}: retry config is only allowed on an action that names an operation`);
368	    }
369	    retry = compileRetry(node.retry, `action node ${node.id}`);
370	  }
371	
372	  let compensation = null;
373	  if (Object.hasOwn(node, 'compensation') && node.compensation !== undefined) {
374	    if (!isUsableObject(node.compensation)) {
375	      throw new Error(`action node ${node.id}: compensation must be an object`);
376	    }
377	    if (!name) {
378	      throw new Error(`action node ${node.id}: compensation is only allowed on an action that names an operation`);
379	    }
380	    const config = node.compensation;
381	    if (typeof config.operation !== 'string' || config.operation.trim().length === 0) {
382	      throw new Error(`action node ${node.id}: compensation.operation must be a non-empty string name`);
383	    }
384	    let compRetry = { ...DEFAULT_RETRY };
385	    if (Object.hasOwn(config, 'retry') && config.retry !== undefined) {
386	      compRetry = compileRetry(config.retry, `action node ${node.id} compensation`);
387	    }
388	    compensation = { name: config.operation, retry: compRetry };
389	  }
390	
391	  return { name, retry, compensation };
392	}
393	
394	// Resolves the outgoing edges of a node. Trigger, form and action nodes may
395	// name a single successor or a non-empty, duplicate-free array of successors;
396	// conditions keep their then/else pair and end nodes have none.
397	function normalizeSuccessors(node, nodes) {
398	  if (node.type === 'end') return [];
399	  if (node.type === 'condition') {
400	    for (const destination of [node.then, node.else]) {
401	      if (typeof destination !== 'string' || !nodes.has(destination)) {
402	        throw new Error(`node ${node.id} points to an unknown destination`);
403	      }
404	    }
405	    return [node.then, node.else];
406	  }
407	  const next = node.next;
408	  if (Array.isArray(next)) {
409	    if (next.length === 0) {
410	      throw new Error(`node ${node.id}: next array must not be empty`);
411	    }
412	    const seen = new Set();
413	    for (const destination of next) {
414	      if (typeof destination !== 'string') {
415	        throw new Error(`node ${node.id}: next array entries must be node id strings`);
416	      }
417	      if (seen.has(destination)) {
418	        throw new Error(`node ${node.id}: duplicate destination ${destination}`);
419	      }
420	      seen.add(destination);
421	      if (!nodes.has(destination)) {
422	        throw new Error(`node ${node.id} points to an unknown destination`);
423	      }
424	    }
425	    return [...seen];
426	  }
427	  if (typeof next !== 'string' || !nodes.has(next)) {
428	    throw new Error(`node ${node.id} points to an unknown destination`);
429	  }
430	  return [next];
431	}
432	
433	// Resolves the explicit dependencies of a node. Dependencies only gate when a
434	// node may run; they never activate it. A missing dependsOn means no
435	// dependencies, and the entry node must not declare any.
436	function normalizeDependencies(node, nodes, entryId) {
437	  if (!Object.hasOwn(node, 'dependsOn') || node.dependsOn === undefined) return [];
438	  if (!Array.isArray(node.dependsOn)) {
439	    throw new Error(`node ${node.id}: dependsOn must be an array`);
440	  }
441	  const seen = new Set();
442	  for (const dependency of node.dependsOn) {
443	    if (typeof dependency !== 'string') {
444	      throw new Error(`node ${node.id}: dependsOn entries must be node id strings`);
445	    }
446	    if (seen.has(dependency)) {
447	      throw new Error(`node ${node.id}: duplicate dependency ${dependency}`);
448	    }
449	    seen.add(dependency);
450	    if (!nodes.has(dependency)) {
451	      throw new Error(`node ${node.id} depends on an unknown node`);
452	    }
453	    if (dependency === node.id) {
454	      throw new Error(`node ${node.id} must not depend on itself`);
455	    }
456	  }
457	  const dependencies = [...seen];
458	  if (node.id === entryId && dependencies.length > 0) {
459	    throw new Error(`entry node ${node.id} must not declare dependencies`);
460	  }
461	  return dependencies;
462	}
463	
464	// Successor edges and dependency ordering constraints together must stay
465	// acyclic across the whole definition — including branches a run would never
466	// take and nodes the entry cannot reach. The error names a node id chain
467	// whose first and last entries match and whose steps are real edges or
468	// dependency relations.
469	//
470	// The search is an iterative three-color DFS with an explicit frame stack:
471	// a recursive walk over a legal definition tens of thousands of chained
472	// nodes deep would overflow the call stack before producing a result. `path`
473	// holds the gray nodes in DFS order (what a recursive stack would hold) and
474	// `depthById` locates a gray node in it, so a back edge still reports
475	// exactly the cycle segment — never the entry path leading into it.
476	function detectCycles(nodes) {
477	  const adjacency = new Map([...nodes.keys()].map(id => [id, []]));
478	  for (const [id, node] of nodes) {
479	    adjacency.get(id).push(...successorTargets.get(node));
480	    for (const dependency of nodeDependencies.get(node)) {
481	      adjacency.get(dependency).push(id);
482	    }
483	  }
484	  const color = new Map([...nodes.keys()].map(id => [id, 'white']));
485	
486	  for (const root of nodes.keys()) {
487	    if (color.get(root) !== 'white') continue;
488	    color.set(root, 'gray');
489	    const path = [root];
490	    const depthById = new Map([[root, 0]]);
491	    // Each frame is [node id, index of the next outgoing edge to examine].
492	    const frames = [[root, 0]];
493	    while (frames.length > 0) {
494	      const frame = frames[frames.length - 1];
495	      const id = frame[0];
496	      const edges = adjacency.get(id);
497	      if (frame[1] < edges.length) {
498	        const target = edges[frame[1]];
499	        frame[1] += 1;
500	        const targetColor = color.get(target);
501	        if (targetColor === 'gray') {
502	          const start = depthById.get(target);
503	          const chain = [...path.slice(start), target];
504	          throw new Error(`cycle is present: ${chain.join(' -> ')}`);
505	        }
506	        if (targetColor === 'white') {
507	          color.set(target, 'gray');
508	          depthById.set(target, path.length);
509	          path.push(target);
510	          frames.push([target, 0]);
511	        }
512	      } else {
