1079	export function executeWorkflow(workflow, input = {}) {
1080	  const nodes = validateWorkflow(workflow);
1081	  // Business operations are asynchronous: the synchronous entry must refuse
1082	  // a workflow that names any before a single node executes.
1083	  for (const node of nodes.values()) {
1084	    const binding = actionBindings.get(node);
1085	    if (binding && binding.name !== null) {
1086	      throw new Error(`action node ${node.id} names business operation "${binding.name}", which must run asynchronously; use executeWorkflowAsync instead of executeWorkflow`);
1087	    }
1088	  }
