1090	  const state = createRunState(nodes, workflow, input);
1091	
1092	  for (;;) {
1093	    const step = advanceSchedule(state);
1094	
1095	    if (step.kind === 'blocked') {
1096	      return { status: 'blocked', context: state.context, trace: state.trace, blockedNodes: step.waiting };
1097	    }
1098	    if (step.kind === 'completed') {
1099	      return { status: 'completed', result: state.endResult, context: state.context, trace: state.trace };
1100	    }
1101	    if (step.kind === 'end') continue;
1102	
1103	    const early = applyRegularNode(step.node, state);
1104	    if (early) return early;
