1108	// Attaches compensation results to a failed run. Successful outputs and the
1109	// original terminal status stay untouched; compensation records live on
1110	// their own fields, never in the regular node trace.
1111	async function withCompensation(result, state, operations) {
1112	  const outcome = await compensateRun(state, operations);
1113	  result.compensationStatus = outcome.attempts.length === 0 ? 'not_needed' : outcome.status;
1114	  result.compensationAttempts = outcome.attempts;
1115	  return result;
1116	}
1117	
1118	// The cancelled terminal shape: the run stops where it is, keeps the
1119	// context, trace and attempt records produced so far, and never carries a
1120	// success result. Compensation for already-succeeded actions is attached by
1121	// withCompensation under the usual rules.
1122	function cancelledResult(state) {
1123	  return {
1124	    status: 'cancelled',
1125	    context: state.context,
1126	    trace: state.trace,
1127	    actionAttempts: state.actionAttempts,
1128	  };
1129	}
