1131	export async function executeWorkflowAsync(workflow, input = {}, operations = {}, options = undefined) {
1132	  const signal = resolveRunSignal(options);
1133	  const nodes = validateWorkflow(workflow);
1134	  verifyOperations(nodes, operations);
1135	
1136	  const state = createRunState(nodes, workflow, input);
1137	
1138	  // A signal that is already aborted stops the run before the first node —
1139	  // but only after the definition and the operation registrations above have
1140	  // been checked. Nothing executes and nothing is compensated.
1141	  if (signal && signal.aborted) {
1142	    return withCompensation(cancelledResult(state), state, operations);
1143	  }
1144	
1145	  for (;;) {
1146	    // Once the signal fires, no new regular node runs and no new business
1147	    // action attempt starts; the run ends cancelled with whatever state it
1148	    // reached, even if an end node was already visited on another branch.
1149	    if (signal && signal.aborted) {
1150	      return withCompensation(cancelledResult(state), state, operations);
1151	    }
