1153	    const step = advanceSchedule(state);
1154	
1155	    if (step.kind === 'blocked') {
1156	      // Unmet dependencies end the run; successful compensable actions are
1157	      // rolled back even though an end node may already have been reached.
1158	      return withCompensation({
1159	        status: 'blocked', context: state.context, trace: state.trace,
1160	        blockedNodes: step.waiting, actionAttempts: state.actionAttempts,
1161	      }, state, operations);
