1	import test from 'node:test';
2	import assert from 'node:assert/strict';
3	import { executeWorkflow, executeWorkflowAsync, validateWorkflow } from '../src/engine.js';
4	
5	const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
6	
7	function linearWorkflow(actionProps = {}, { actionMessage = false } = {}) {
8	  return {
9	    id: 'ops',
10	    entry: 'start',
11	    nodes: [
12	      { id: 'start', type: 'trigger', next: 'prep' },
13	      { id: 'prep', type: 'action', message: 'prepared', next: 'work' },
14	      {
15	        id: 'work', type: 'action',
16	        ...(actionMessage ? { message: 'legacy' } : actionProps),
17	        next: 'done',
18	      },
19	      { id: 'done', type: 'end', result: 'finished' },
20	    ],
21	  };
22	}
23	
24	test('legacy message actions keep working through the asynchronous entry', async () => {
25	  const execution = await executeWorkflowAsync(linearWorkflow(null, { actionMessage: true }), { x: 1 });
26	  assert.equal(execution.status, 'completed');
27	  assert.equal(execution.context.output.work, 'legacy');
28	  assert.deepEqual(execution.actionAttempts, []);
29	  assert.deepEqual(execution.trace.map(n => n.nodeId), ['start', 'prep', 'work', 'done']);
30	});
31	
32	test('synchronous execution, validation and legacy behavior are unchanged for message actions', () => {
33	  const execution = executeWorkflow(linearWorkflow(null, { actionMessage: true }), {});
